BOOST_AUTO_TEST_CASE(test_pulse_id_increment_and_override)
{
    const std::string path = testdata_path("uwb_radar/tx_998p4.cf32");
    auto blk = UwbRadarPacketSource::make(path, 998.4e6);

    pmt::pmt_t a = run_emit(blk, pmt::PMT_NIL);
    BOOST_CHECK_EQUAL(dict_i64(pmt::car(a), "pulse_id", -1), 0);

    pmt::pmt_t b = run_emit(blk, pmt::make_dict());
    BOOST_CHECK_EQUAL(dict_i64(pmt::car(b), "pulse_id", -1), 1);

    pmt::pmt_t dict = pmt::make_dict();
    dict = pmt::dict_add(dict, pmt::mp("pulse_id"), pmt::from_uint64(7));
    pmt::pmt_t c = run_emit(blk, dict);
    BOOST_CHECK_EQUAL(dict_i64(pmt::car(c), "pulse_id", -1), 7);
}

