bool throws_make(const std::string& path,
                 double rate,
                 const std::string& fmt,
                 size_t sync = 64,
                 const std::string& sfd = "4z2",
                 size_t code = 9,
                 const std::string& descriptor = "")
{
    try {
        (void)UwbRadarPacketSource::make(
            path, rate, fmt, sync, sfd, code, 0.005, false, descriptor);
        return false;
    } catch (const std::exception&) {
        return true;
    }
}

bool load_sc16(const std::string& path, std::vector<int16_t>& out)
{
    std::ifstream f(path, std::ios::binary | std::ios::ate);
    if (!f)
        return false;
    const auto bytes = static_cast<size_t>(f.tellg());
    if (bytes == 0 || bytes % sizeof(int16_t) != 0)
        return false;
    f.seekg(0);
    out.resize(bytes / sizeof(int16_t));
    f.read(reinterpret_cast<char*>(out.data()),
           static_cast<std::streamsize>(bytes));
    return static_cast<bool>(f);
}

void write_descriptor(const std::string& path,
                      const std::string& sample_format,
                      const std::string& dtype,
                      const std::string& byte_order,
                      const std::string& layout,
                      int64_t length)
{
    std::ofstream f(path, std::ios::binary | std::ios::trunc);
    BOOST_REQUIRE_MESSAGE(f, "cannot create " + path);
    f << "{\"sample_format\":\"" << sample_format
      << "\",\"dtype\":\"" << dtype
      << "\",\"byte_order\":\"" << byte_order
      << "\",\"layout\":\"" << layout
      << "\",\"bytes_per_complex\":"
      << (sample_format == "fc32" ? 8 : 4)
      << ",\"rate_work_hz\":998400000"
      << ",\"rate_native_hz\":737280000"
      << ",\"sync_repetitions\":64"
      << ",\"sfd_mode\":\"4z2\""
      << ",\"code_index\":9"
      << ",\"tx_length_998p4\":" << length
      << ",\"tx_length_737p28\":" << length << "}";
    BOOST_REQUIRE_MESSAGE(f.good(), "failed writing " + path);
}

