BOOST_AUTO_TEST_CASE(test_sc16_998p4_golden)
{
    const std::string path = testdata_path("uwb_radar/tx_998p4.sc16");
    const std::string head = testdata_path("uwb_radar/tx_998p4_sc16_head16.i16");
    std::vector<int16_t> file, head16;
    BOOST_REQUIRE_MESSAGE(load_sc16(path, file), "cannot load " + path);
    BOOST_REQUIRE_MESSAGE(load_sc16(head, head16), "cannot load " + head);
    BOOST_REQUIRE_EQUAL(file.size(), 190912u * 2u);
    BOOST_REQUIRE_EQUAL(head16.size(), 32u);
    BOOST_REQUIRE_EQUAL(std::memcmp(file.data(), head16.data(),
                                    head16.size() * sizeof(int16_t)),
                        0);

    auto blk = UwbRadarPacketSource::make(path, 998.4e6, "sc16");
    BOOST_REQUIRE_EQUAL(blk->num_samples(), 190912u);
    BOOST_REQUIRE_EQUAL(blk->sc16_samples().size(), file.size());
    BOOST_REQUIRE_EQUAL(std::memcmp(blk->sc16_samples().data(), file.data(),
                                    file.size() * sizeof(int16_t)),
                        0);

    pmt::pmt_t pdu = run_emit(blk, pmt::make_dict());
    BOOST_REQUIRE(pmt::is_pair(pdu));
    pmt::pmt_t meta = pmt::car(pdu);
    pmt::pmt_t data = pmt::cdr(pdu);
    BOOST_REQUIRE(pmt::is_s16vector(data));
    BOOST_REQUIRE(!pmt::is_c32vector(data));
    size_t n = 0;
    const int16_t* p = pmt::s16vector_elements(data, n);
    BOOST_REQUIRE_EQUAL(n, file.size());
    BOOST_REQUIRE_EQUAL(std::memcmp(p, file.data(),
                                    file.size() * sizeof(int16_t)),
                        0);
    BOOST_CHECK_EQUAL(dict_str(meta, "sample_format"), std::string("sc16"));
    BOOST_CHECK_CLOSE(dict_f64(meta, "sample_rate", 0.0), 998.4e6, 1e-4);
    BOOST_CHECK_EQUAL(dict_i64(meta, "tx_packet_samples", -1), 190912);
    BOOST_CHECK_EQUAL(dict_i64(meta, "sample_count", -1), 190912);
    BOOST_CHECK_EQUAL(dict_i64(meta, "sync_repetitions", -1), 64);
    BOOST_CHECK_EQUAL(dict_str(meta, "sfd_mode"), std::string("4z2"));
    BOOST_CHECK_EQUAL(dict_i64(meta, "code_index", -1), 9);
}

