BOOST_AUTO_TEST_CASE(test_descriptor_binds_sample_format_and_byte_layout)
{
    // Native rate avoids the work-domain SYNC+SFD minimum-length check: both
    // files deliberately decode to four complex samples, so a rejection here
    // can only come from the descriptor's byte-format contract.
    const std::string fc32_path = "/tmp/uwb_qa_descriptor_fc32.bin";
    const std::string sc16_path = "/tmp/uwb_qa_descriptor_sc16.bin";
    const std::string fc32_desc = "/tmp/uwb_qa_descriptor_fc32.json";
    const std::string sc16_desc = "/tmp/uwb_qa_descriptor_sc16.json";
    const std::string bad_order_desc = "/tmp/uwb_qa_descriptor_bad_order.json";

    const std::vector<gr_complex> fc32(4, gr_complex(0.25f, -0.5f));
    {
        std::ofstream f(fc32_path, std::ios::binary | std::ios::trunc);
        BOOST_REQUIRE(f);
        f.write(reinterpret_cast<const char*>(fc32.data()),
                static_cast<std::streamsize>(fc32.size() * sizeof(gr_complex)));
        BOOST_REQUIRE(f.good());
    }
    const std::vector<int16_t> sc16 = { 100, -200, 300, -400,
                                        500, -600, 700, -800 };
    {
        std::ofstream f(sc16_path, std::ios::binary | std::ios::trunc);
        BOOST_REQUIRE(f);
        f.write(reinterpret_cast<const char*>(sc16.data()),
                static_cast<std::streamsize>(sc16.size() * sizeof(int16_t)));
        BOOST_REQUIRE(f.good());
    }

    write_descriptor(fc32_desc, "fc32", "complex64", "little-endian",
                     "interleaved_iq", 4);
    write_descriptor(sc16_desc, "sc16", "int16", "little-endian",
                     "interleaved_iq", 4);
    write_descriptor(bad_order_desc, "fc32", "complex64", "big-endian",
                     "interleaved_iq", 4);

    // The matching descriptor permits the tiny native fixture.
    auto ok = UwbRadarPacketSource::make(
        fc32_path, 737.28e6, "fc32", 64, "4z2", 9, 0.005, false, fc32_desc);
    BOOST_CHECK_EQUAL(ok->num_samples(), 4u);

    // Both files present exactly four samples in their selected format. A
    // length-only descriptor check would accept these two calls.
    BOOST_REQUIRE(throws_make(fc32_path, 737.28e6, "fc32", 64, "4z2", 9,
                              sc16_desc));
    BOOST_REQUIRE(throws_make(sc16_path, 737.28e6, "sc16", 64, "4z2", 9,
                              fc32_desc));
    BOOST_REQUIRE(throws_make(fc32_path, 737.28e6, "fc32", 64, "4z2", 9,
                              bad_order_desc));
}

BOOST_AUTO_TEST_CASE(test_unsupported_sync_reps_throws)
{
    const std::string path = testdata_path("uwb_radar/tx_998p4.cf32");
    BOOST_REQUIRE(throws_make(path, 998.4e6, "fc32", 16));
    BOOST_REQUIRE(throws_make(path, 998.4e6, "fc32", 0));
    BOOST_REQUIRE(throws_make(path, 998.4e6, "fc32", 48));
    BOOST_REQUIRE(throws_make(path, 998.4e6, "fc32", 4096));
    BOOST_CHECK(gr::uwb::radar_meta::sync_reps_supported(32));
    BOOST_CHECK(gr::uwb::radar_meta::sync_reps_supported(256));
    BOOST_CHECK(gr::uwb::radar_meta::sync_reps_supported(512));
    BOOST_CHECK(gr::uwb::radar_meta::sync_reps_supported(1024));
    BOOST_CHECK(gr::uwb::radar_meta::sync_reps_supported(2048));
    BOOST_CHECK(!gr::uwb::radar_meta::sync_reps_supported(4096));
}

BOOST_AUTO_TEST_CASE(test_sync256_min_length_work_packet)
{
    const size_t n_sync = 256;
    const size_t n = n_sync * 1016 + 8 * 1016;
    const std::string path = "/tmp/uwb_qa_sync256_min.cf32";
    {
        std::vector<gr_complex> z(n, gr_complex(0.01f, 0.0f));
        std::ofstream f(path, std::ios::binary);
        BOOST_REQUIRE(f);
        f.write(reinterpret_cast<const char*>(z.data()),
                static_cast<std::streamsize>(n * sizeof(gr_complex)));
    }
    auto blk = UwbRadarPacketSource::make(path, 998.4e6, "fc32", n_sync);
    BOOST_CHECK_EQUAL(blk->num_samples(), n);
    BOOST_CHECK_EQUAL(blk->sync_repetitions(), n_sync);
    pmt::pmt_t pdu = run_emit(blk, pmt::make_dict());
    BOOST_REQUIRE(pmt::is_pair(pdu));
    BOOST_CHECK_EQUAL(dict_i64(pmt::car(pdu), "sync_repetitions", -1),
                      static_cast<int64_t>(n_sync));
    BOOST_CHECK_EQUAL(dict_i64(pmt::car(pdu), "sync_samples", -1),
                      static_cast<int64_t>(n_sync * 1016));
}
